def lot_and_line_of_each_partnership(apps, schema_editor):
    """Every partnership so far shares the one line it was made on, in that line's lot (D-320)."""
    Partnership = apps.get_model("partnerships", "LotPartnership")
    Line = apps.get_model("partnerships", "PartnershipLine")
    for partnership in Partnership.objects.select_related("batch"):
        partnership.lot_id = partnership.batch.lot_id
        partnership.save(update_fields=["lot"])
        Line.objects.create(
            organization_id=partnership.organization_id, partnership=partnership, batch_id=partnership.batch_id
        )


